import json
import re
import pandas as pd
def task_func(json_str):
    try:
        data = json.loads(json_str)
    except:
        return pd.DataFrame()

    if not isinstance(data, dict):
        return pd.DataFrame()

    def normalize(val):
        if isinstance(val, (int, float)):
            return float(val * 2)
        elif isinstance(val, str):
            if re.match(r'^-?\d+(\.\d+)?$', val.strip()):
                return float(val) * 2
            return val
        elif isinstance(val, list):
            return [normalize(item) for item in val]
        else:
            return val

    processed = {k: normalize(v) for k, v in data.items()}

    try:
        df = pd.DataFrame(processed)
        return df
    except:
        return pd.DataFrame()

